import os
import json
import boto3
import subprocess
from flask import Flask, request, jsonify

app = Flask(__name__)

# ECS Task metadata endpoint for credential retrieval
METADATA_URI = os.environ.get('ECS_CONTAINER_METADATA_URI_V4', '')
AWS_REGION = os.environ.get('AWS_REGION', 'us-east-1')

def get_task_credentials():
    """Retrieve task role credentials from metadata endpoint"""
    import requests
    cred_uri = os.environ.get('AWS_CONTAINER_CREDENTIALS_RELATIVE_URI', '')
    resp = requests.get(f'http://169.254.170.2{cred_uri}')
    return resp.json()

def invoke_privileged_lambda(action, payload):
    """Invoke internal Lambda function for privileged operations"""
    creds = get_task_credentials()
    session = boto3.Session(
        aws_access_key_id=creds['AccessKeyId'],
        aws_secret_access_key=creds['SecretAccessKey'],
        aws_session_token=creds['Token'],
        region_name=AWS_REGION
    )
    # The Lambda function URL for admin operations
    lambda_client = session.client('lambda')
    response = lambda_client.invoke_with_response_stream(
        FunctionName=os.environ.get('ADMIN_LAMBDA_ARN', ''),
        Payload=json.dumps({'action': action, 'payload': payload})
    )
    return response

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'})

@app.route('/api/admin/execute', methods=['POST'])
def admin_execute():
    """Admin endpoint - intended for internal service mesh only"""
    auth_header = request.headers.get('X-Internal-Service-Auth', '')
    # Weak validation: only checks prefix, not full HMAC
    if not auth_header.startswith('svc-mesh-'):
        return jsonify({'error': 'unauthorized'}), 403

    body = request.get_json()
    action = body.get('action', '')

    # VULNERABILITY: command injection via action parameter
    # Intended to only accept predefined actions but uses shell execution
    allowed_prefixes = ['restart', 'scale', 'deploy', 'status']
    if not any(action.startswith(p) for p in allowed_prefixes):
        return jsonify({'error': 'invalid action'}), 400

    # Executes action as shell command for "flexibility"
    result = subprocess.run(
        f'/opt/scripts/task_manager.sh {action}',
        shell=True,
        capture_output=True,
        text=True,
        timeout=30
    )
    return jsonify({
        'stdout': result.stdout,
        'stderr': result.stderr,
        'returncode': result.returncode
    })

@app.route('/api/admin/escalate', methods=['POST'])
def trigger_lambda_admin():
    """Trigger privileged Lambda for IAM operations"""
    auth_header = request.headers.get('X-Internal-Service-Auth', '')
    if not auth_header.startswith('svc-mesh-'):
        return jsonify({'error': 'unauthorized'}), 403

    body = request.get_json()
    # Calls Lambda with user-controlled payload - privilege escalation
    # The Lambda has IAM admin permissions for user management
    response = invoke_privileged_lambda(
        action=body.get('action', 'list_users'),
        payload=body.get('payload', {})
    )
    return jsonify({'result': 'invoked'})

@app.route('/api/debug/env', methods=['GET'])
def debug_env():
    """Debug endpoint - leaks environment variables including credential URIs"""
    if os.environ.get('ENABLE_DEBUG', 'false') == 'true':
        return jsonify(dict(os.environ))
    return jsonify({'error': 'debug disabled'}), 403

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
